import{_ as n,C as r,o as i,c as a,a2 as t,E as o}from"./chunks/framework.TaNiW7i8.js";const v=JSON.parse('{"title":"Connecter ses agents","description":"","frontmatter":{"title":"Connecter ses agents"},"headers":[],"relativePath":"guide/agents.md","filePath":"guide/agents.md"}'),l={name:"guide/agents.md"};function c(d,e,u,g,p,h){const s=r("Capture");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="connecter-ses-agents" tabindex="-1">Connecter ses agents <a class="header-anchor" href="#connecter-ses-agents" aria-label="Permalink to &quot;Connecter ses agents&quot;">​</a></h1><p>Pour qu&#39;un assistant IA lise et enrichisse votre mémoire, il doit connaître le serveur MCP de Kessho, <code>kessho-mcp</code>. Kessho le déclare lui-même dans les assistants installés sur votre poste, en un clic. Cette page montre comment, et ce que Kessho écrit exactement chez eux.</p><h2 id="les-assistants-pris-en-charge" tabindex="-1">Les assistants pris en charge <a class="header-anchor" href="#les-assistants-pris-en-charge" aria-label="Permalink to &quot;Les assistants pris en charge&quot;">​</a></h2><p>Kessho déclare son serveur chez ces dix clients :</p><table tabindex="0"><thead><tr><th>Client</th><th>Fichier de configuration modifié</th></tr></thead><tbody><tr><td>Claude Code</td><td><code>~/.claude.json</code></td></tr><tr><td>Claude Desktop</td><td><code>~/Library/Application Support/Claude/claude_desktop_config.json</code> (macOS)</td></tr><tr><td>Codex</td><td><code>~/.codex/config.toml</code></td></tr><tr><td>Gemini CLI</td><td><code>~/.gemini/settings.json</code></td></tr><tr><td>Mistral Vibe</td><td><code>~/.vibe/config.toml</code></td></tr><tr><td>GitHub Copilot CLI</td><td><code>~/.copilot/mcp-config.json</code></td></tr><tr><td>Antigravity</td><td><code>~/.gemini/config/mcp_config.json</code></td></tr><tr><td>Antigravity (application)</td><td><code>~/.gemini/antigravity/mcp_config.json</code></td></tr><tr><td>Antigravity (CLI)</td><td><code>~/.gemini/antigravity-cli/mcp_config.json</code></td></tr><tr><td>opencode</td><td><code>~/.config/opencode/opencode.json</code></td></tr></tbody></table><p>Un client qui n&#39;est pas installé est affiché « Non détecté » : Kessho n&#39;écrit aucune déclaration chez lui. En revanche, <strong>Auto-injecter</strong> fait aussi un ménage d&#39;anciens résidus Antigravity et Gemini (ancienne extension <code>memory-kit</code> et ses entrées d&#39;activation dans <code>~/.gemini/</code>), avec une sauvegarde avant chaque modification.</p><h2 id="ce-que-kessho-ecrit" tabindex="-1">Ce que Kessho écrit <a class="header-anchor" href="#ce-que-kessho-ecrit" aria-label="Permalink to &quot;Ce que Kessho écrit&quot;">​</a></h2><ul><li>Une entrée nommée <code>kessho</code>, qui indique le programme <code>kessho-mcp</code>, cherché à côté de l&#39;application puis dans le <code>PATH</code>. Elle ne porte <strong>aucun argument</strong> : le serveur retrouve votre mémoire tout seul.</li><li><strong>Une sauvegarde d&#39;abord</strong> : avant de modifier un fichier, Kessho en garde une copie à côté, nommée <code>&lt;fichier&gt;.bak.&lt;horodatage&gt;</code>. Si la sauvegarde échoue, rien n&#39;est écrit.</li><li><strong>Aucune permission accordée</strong> : Kessho n&#39;ajoute rien aux listes d&#39;autorisations de vos assistants.</li><li><strong>Aucun programme lancé</strong> pour déclarer le serveur : Kessho écrit dans le fichier, point.</li><li>Les déclarations héritées d&#39;un ancien serveur sont retirées du fichier au passage, et l&#39;écran le dit (« Déclarations héritées retirées »).</li></ul><h2 id="declarer-kessho-a-vos-assistants" tabindex="-1">Déclarer Kessho à vos assistants <a class="header-anchor" href="#declarer-kessho-a-vos-assistants" aria-label="Permalink to &quot;Déclarer Kessho à vos assistants&quot;">​</a></h2>',9)),o(s,{name:"connecteurs",alt:"L'écran des connecteurs d'agents MCP : la liste des clients avec leur état et leur fichier de configuration, les boutons « Sonder le serveur », « Auto-injecter » et « Désinstaller »."}),e[1]||(e[1]=t('<ol><li>Ouvrez <strong>Réglages</strong>, puis la section <strong>Connecteurs MCP</strong>.</li><li>Le tableau liste chaque client avec son <strong>État</strong> et le fichier de <strong>Configuration</strong>. Au-dessus, des compteurs résument : « 8 déployés », « 0 à configurer », « 0 résidu ».</li><li>Cliquez sur <strong>Auto-injecter</strong>. Il agit sur tous les clients détectés à la fois : il n&#39;existe pas de déploiement client par client.</li><li>Chaque client détecté passe à <strong>Déployé</strong>. Le panneau <strong>Déploiement</strong> à droite donne les deux comptes : <strong>Clients détectés</strong> et <strong>Déclarations écrites</strong>.</li></ol><p>Pendant l&#39;assistant de <a href="/Kessho/guide/first-run.html">premier lancement</a>, l&#39;étape <strong>Connecteurs</strong> fait la même chose avec le bouton <strong>Déclarer Kessho à mes assistants</strong>.</p><p>Si macOS affiche « macOS fait tourner une copie temporaire », déplacez Kessho dans le dossier Applications avec le Finder (glisser-déposer, pas copier), puis relancez-le. Sinon, Kessho inscrirait chez vos outils un chemin qui disparaît à la fermeture.</p><h2 id="lire-l-etat-d-un-client" tabindex="-1">Lire l&#39;état d&#39;un client <a class="header-anchor" href="#lire-l-etat-d-un-client" aria-label="Permalink to &quot;Lire l&#39;état d&#39;un client&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Libellé</th><th>Ce que cela veut dire</th></tr></thead><tbody><tr><td><strong>Déployé</strong></td><td>Le client est détecté et Kessho est déclaré dans sa configuration.</td></tr><tr><td><strong>À configurer</strong></td><td>Le client est installé, mais Kessho n&#39;y est pas encore déclaré. Cliquez sur <strong>Auto-injecter</strong>.</td></tr><tr><td><strong>Non détecté</strong></td><td>Le client n&#39;est pas installé sur ce poste. Ce n&#39;est pas une panne.</td></tr><tr><td><strong>Résidu</strong></td><td>Le client a quitté la machine ; sa déclaration est encore écrite.</td></tr><tr><td><strong>Échec du déploiement</strong></td><td>L&#39;écriture a échoué. Passez la souris sur l&#39;état : la raison s&#39;affiche.</td></tr></tbody></table><p>Sans ouvrir les réglages, vous voyez aussi l&#39;essentiel ailleurs : la barre d&#39;état en bas affiche <strong>AGENTS 6/8</strong> (nombre de clients détectés qui portent Kessho, sur le nombre de clients détectés), et l&#39;accueil montre la carte <strong>État de la machine</strong> avec <strong>Ouvrir les réglages</strong>.</p><h2 id="verifier-que-le-serveur-repond" tabindex="-1">Vérifier que le serveur répond <a class="header-anchor" href="#verifier-que-le-serveur-repond" aria-label="Permalink to &quot;Vérifier que le serveur répond&quot;">​</a></h2><p>Cliquez sur <strong>Sonder le serveur</strong>. Kessho lance son propre serveur et mesure sa réponse :</p><ul><li>« Serveur joignable · 42 ms » : tout va bien ;</li><li>« Serveur muet » : il a démarré mais n&#39;a pas répondu à temps ;</li><li>« Binaire introuvable » : le programme déclaré n&#39;existe pas ou n&#39;a pas pu être lancé ;</li><li>« Sonde impossible » : la vérification elle-même a échoué.</li></ul><p>La sonde teste <strong>le serveur de Kessho</strong>, pas vos assistants : elle ne dit rien sur le fait qu&#39;un client l&#39;utilise.</p><h2 id="essayer-un-outil-sans-risque" tabindex="-1">Essayer un outil sans risque <a class="header-anchor" href="#essayer-un-outil-sans-risque" aria-label="Permalink to &quot;Essayer un outil sans risque&quot;">​</a></h2><p>En bas à gauche, le <strong>Banc d&#39;essai</strong> (étiqueté « simulation ») permet de voir à quoi ressemble un appel d&#39;outil.</p><ol><li>Choisissez un outil dans la liste. Ceux qui écrivent sont marqués « écrit » ; ceux qui ne sont pas encore disponibles, « non implémenté » (non sélectionnables).</li><li>Ajustez la <strong>Charge JSON</strong> si besoin.</li><li>Cliquez sur <strong>Lancer</strong>.</li></ol><p>Le banc <strong>n&#39;exécute rien</strong> : il vérifie que votre JSON est valide et le renvoie en écho. Aucune donnée de la mémoire n&#39;est lue ni écrite. La liste complète des outils est dans la <a href="/Kessho/reference/mcp/">Référence MCP</a>.</p><h2 id="retirer-kessho-d-un-client" tabindex="-1">Retirer Kessho d&#39;un client <a class="header-anchor" href="#retirer-kessho-d-un-client" aria-label="Permalink to &quot;Retirer Kessho d&#39;un client&quot;">​</a></h2><ol><li>Dans le tableau, cliquez sur la ligne du client (une deuxième fois la désélectionne).</li><li>Cliquez sur <strong>Désinstaller</strong>. Le bouton n&#39;est actif que pour un client <strong>Déployé</strong> ou <strong>Résidu</strong>.</li><li>Lisez la confirmation : « Retire l&#39;entrée Kessho de … Aucune permission n&#39;est modifiée. »</li><li>Cliquez sur <strong>Confirmer le retrait</strong>, ou sur <strong>Annuler</strong>.</li></ol><p>Seule l&#39;entrée de Kessho est retirée, et une sauvegarde est prise si le fichier change. Si le retrait échoue, l&#39;écran nomme le client concerné.</p><h2 id="l-ancien-serveur" tabindex="-1">L&#39;ancien serveur <a class="header-anchor" href="#l-ancien-serveur" aria-label="Permalink to &quot;L&#39;ancien serveur&quot;">​</a></h2><p>Si un ancien serveur de Kessho est encore sur votre disque, le panneau <strong>Déploiement</strong> le signale (« Ancien serveur encore installé ») : plus aucun client ne le lance. Le bouton <strong>Retirer ce binaire</strong> le supprime après confirmation, et une copie est conservée avant suppression.</p><h2 id="et-ensuite" tabindex="-1">Et ensuite ? <a class="header-anchor" href="#et-ensuite" aria-label="Permalink to &quot;Et ensuite ?&quot;">​</a></h2><p>Une fois vos assistants connectés, vous parlez à votre mémoire par eux : voir <a href="/Kessho/agent/">Avec un agent</a>.</p>',21))])}const f=n(l,[["render",c]]);export{v as __pageData,f as default};
